        except subprocess.CalledProcessError as e:
            return TypeCheckResult("Type check failed", False, str(e))

        # Parse the output to identify lines with expected type errors
        errors = []
        for line in output.split("\n"):
            if "error" in line:
                errors.append(line)

        # Return the result of the type check
        if errors:
            return TypeCheckResult("Type check failed", False, "\n".join(errors))
        else:
            return TypeCheckResult("Type check passed", True, "")
